/** Spacing (dp). There is no space-7: the scale goes from space-6 (24) straight to space-8 (32). */
object TmlSpacing {
    /** Gap between an icon and its label inside a pill; half-step of the 8pt grid. */
    val Space1: Dp = 4.dp
    /** Inset of floating sheets and bars from the screen edge; gap between stacked buttons. */
    val Space2: Dp = 8.dp
    /** Gap between an avatar and its text in a row; padding inside small cards. */
    val Space3: Dp = 12.dp
    /** Screen margins on standard phones; list row side padding. */
    val Space4: Dp = 16.dp
    /** Screen margins on larger phones; padding inside map sheets. */
    val Space5: Dp = 20.dp
    /** Gap between sections on a screen. */
    val Space6: Dp = 24.dp
    /** Gap above a screen's primary action when the screen has room. */
    val Space8: Dp = 32.dp
    /** Minimum height and width of anything tappable: 44pt on iOS. */
    val TapTarget: Dp = 44.dp
    /** Minimum height and width of anything tappable on Android (48dp) and on the viewer's browser page (48px). */
    val TapTargetLg: Dp = 48.dp
}

/** The cross-platform radii (dp), as on iOS and the web. Android components use [TmlAndroidRadius]. */
object TmlRadius {
    /** Small thumbnails and keycap-sized elements. */
    val Xs: Dp = 8.dp
    /** Tiles and neutral buttons inside a map sheet (radius-sheet minus 20pt padding, so corners stay concentric). */
    val Md: Dp = 18.dp
    /** Grouped lists, cards and map previews. */
    val Lg: Dp = 26.dp
    /** Floating sheets and the picture-in-picture mini map, following the device's corners. */
    val Sheet: Dp = 38.dp
    /** Buttons, status pills, name capsules and the distance capsule. */
    val Pill: Dp = 999.dp
}

/** Material 3 corner radii for the Android app (dp). Documentation only: Material 3 corner radii for the Android app, in dp (written as px like the rest of this file). Not built into tokens.css. */
object TmlAndroidRadius {
    /** Cards. */
    val Card: Dp = 24.dp
    /** Dialogs and modal bottom sheets. */
    val Dialog: Dp = 28.dp
    /** Outer corners of a grouped list (first and last rows). */
    val ListOuter: Dp = 20.dp
    /** Inner corners between rows of a grouped list, with 2dp gaps. */
    val ListInner: Dp = 4.dp
    /** Text fields. */
    val Field: Dp = 4.dp
    /** Buttons while pressed; they morph from fully round at rest. */
    val Pressed: Dp = 10.dp
}

/** A CSS-style shadow: offset, blur radius and color. */
@Immutable
data class TmlShadow(val offsetX: Dp, val offsetY: Dp, val blur: Dp, val color: Color)

/** Shadows go on three things only: markers (shadow-marker), the floating mini map (shadow-float) and Android's system stand-ins (a soft shadow of their own). Never on glass, which separates with glass-edge. */
object TmlShadows {
    /** Person markers on the map. */
    val MarkerLight = TmlShadow(0.dp, 6.dp, 16.dp, Color(0x4011181B))
    /** Dark theme. Person markers on the map. */
    val MarkerDark = TmlShadow(0.dp, 8.dp, 20.dp, Color(0x8C000000))
    /** The Android picture-in-picture mini map floating over the call screen. */
    val FloatLight = TmlShadow(0.dp, 18.dp, 48.dp, Color(0x2E11181B))
    /** Dark theme. The Android picture-in-picture mini map floating over the call screen. */
    val FloatDark = TmlShadow(0.dp, 24.dp, 60.dp, Color(0x99000000))
}

// ---------- Type ----------

/**
 * The token type scale in the given families: Gabarito for [display], Figtree for [text] on Android.
 * Sizes are sp, so they follow the system font scale.
 * CSS stacks: display "Gabarito", -apple-system, BlinkMacSystemFont, system-ui, sans-serif; text -apple-system, BlinkMacSystemFont, "SF Pro Text", "Figtree", system-ui, sans-serif.
 */
@Immutable
class TmlTypeScale(val display: FontFamily = FontFamily.Default, val text: FontFamily = FontFamily.Default) {
    /** The one big title at the top of Home and the share screen. Gabarito Bold, bundled in the app and scaled with Dynamic Type. (Titles; 34/41, weight 700. Sample: "Share where you are") */
    val largeTitle = TextStyle(fontFamily = display, fontWeight = FontWeight.W700, fontSize = 34.0.sp, lineHeight = 41.0.sp, letterSpacing = (-0.6).sp)
    /** Screen titles on pushed screens. Gabarito Bold, scaled with Dynamic Type. (Titles; 28/34, weight 700. Sample: "Your mascot") */
    val title1 = TextStyle(fontFamily = display, fontWeight = FontWeight.W700, fontSize = 28.0.sp, lineHeight = 34.0.sp, letterSpacing = (-0.45).sp)
    /** Sheet titles over the map. Gabarito Bold, scaled with Dynamic Type. (Titles; 22/28, weight 700. Sample: "You're both live") */
    val title2 = TextStyle(fontFamily = display, fontWeight = FontWeight.W700, fontSize = 22.0.sp, lineHeight = 28.0.sp, letterSpacing = (-0.3).sp)
    /** Section heads and the viewer page's heading. iOS: .title3. (Text; 20/25, weight 600. Sample: "Alex is sharing their location with you") */
    val title3 = TextStyle(fontFamily = text, fontWeight = FontWeight.W600, fontSize = 20.0.sp, lineHeight = 25.0.sp, letterSpacing = (-0.45).sp)
    /** Button labels and list row titles. iOS: .headline. (Text; 17/22, weight 600. Sample: "Share live location") */
    val headline = TextStyle(fontFamily = text, fontWeight = FontWeight.W600, fontSize = 17.0.sp, lineHeight = 22.0.sp, letterSpacing = (-0.43).sp)
    /** Default reading text. iOS: .body. (Text; 17/22, weight 400. Sample: "The person you're talking to follows you live in their browser.") */
    val body = TextStyle(fontFamily = text, fontWeight = FontWeight.Normal, fontSize = 17.0.sp, lineHeight = 22.0.sp, letterSpacing = (-0.43).sp)
    /** Sheet subtitles and explanations under a title. iOS: .callout. (Text; 16/21, weight 400. Sample: "Visible until your call ends.") */
    val callout = TextStyle(fontFamily = text, fontWeight = FontWeight.Normal, fontSize = 16.0.sp, lineHeight = 21.0.sp, letterSpacing = (-0.31).sp)
    /** List row details and status text. iOS: .subheadline. (Text; 15/20, weight 400. Sample: "Sharing back · updated 3 s ago") */
    val subheadline = TextStyle(fontFamily = text, fontWeight = FontWeight.Normal, fontSize = 15.0.sp, lineHeight = 20.0.sp, letterSpacing = (-0.23).sp)
    /** Small print under buttons and inside pills. iOS: .footnote. (Text; 13/18, weight 400. Sample: "Your browser will ask for permission first.") */
    val footnote = TextStyle(fontFamily = text, fontWeight = FontWeight.Normal, fontSize = 13.0.sp, lineHeight = 18.0.sp, letterSpacing = (-0.08).sp)
    /** Name capsules under map markers. iOS: .caption with medium weight. (Text; 12/16, weight 500. Sample: "Alex") */
    val caption1 = TextStyle(fontFamily = text, fontWeight = FontWeight.W500, fontSize = 12.0.sp, lineHeight = 16.0.sp, letterSpacing = 0.0.sp)
    /** The smallest allowed text: map labels only, never below 11pt, growing with the text size. Sentence case or the place's own name, never uppercase. iOS: .caption2. (Text; 11/13, weight 400. Sample: "Alder Park") */
    val caption2 = TextStyle(fontFamily = text, fontWeight = FontWeight.Normal, fontSize = 11.0.sp, lineHeight = 13.0.sp, letterSpacing = 0.06.sp)
    /** The big distance on the Live Activity and stat tiles. Gabarito Bold; tabular figures on iOS come from SF Pro with .monospacedDigit(). (Numbers; 28/34, weight 700. Sample: "1.2 km") */
    val distance = TextStyle(fontFamily = display, fontWeight = FontWeight.W700, fontSize = 28.0.sp, lineHeight = 34.0.sp, letterSpacing = (-0.4).sp)
    /** Numbers inline: the distance capsule on the map, call timers. (Numbers; 15/20, weight 700. Sample: "1.2 km · 04:12") */
    val metric = TextStyle(fontFamily = display, fontWeight = FontWeight.W700, fontSize = 15.0.sp, lineHeight = 20.0.sp, letterSpacing = (-0.1).sp)
    /** Uppercase status badges (LIVE, LIVE TOGETHER, NO SIGNAL, NO CONNECTION). The only uppercase text anywhere. (Numbers; 11/13, weight 800. Sample: "LIVE") */
    val badge = TextStyle(fontFamily = display, fontWeight = FontWeight.W800, fontSize = 11.0.sp, lineHeight = 13.0.sp, letterSpacing = 0.6.sp)
}

/** The current [TmlTypeScale]; provided by [TmlTheme]. */
val LocalTmlTypeScale = staticCompositionLocalOf { TmlTypeScale() }

/**
 * Material 3 [Typography] from the token scale. Roles without a token (display*, labelLarge) keep
 * Material's default size in the matching family.
 */
fun tmlTypography(scale: TmlTypeScale): Typography {
    val base = Typography()
    return Typography(
        displayLarge = base.displayLarge.copy(fontFamily = scale.display),
        displayMedium = base.displayMedium.copy(fontFamily = scale.display),
        displaySmall = base.displaySmall.copy(fontFamily = scale.display),
        labelLarge = base.labelLarge.copy(fontFamily = scale.text),
        headlineLarge = scale.largeTitle,
        headlineMedium = scale.title1,
        headlineSmall = scale.title2,
        titleLarge = scale.title2,
        titleMedium = scale.title3,
        titleSmall = scale.headline,
        bodyLarge = scale.body,
        bodyMedium = scale.subheadline,
        bodySmall = scale.footnote,
        labelMedium = scale.caption1,
        labelSmall = scale.caption2,
    )
}

// ---------- Theme ----------

/**
 * MaterialTheme in Track Me Live tokens, plus [LocalTmlColors] and [LocalTmlTypeScale].
 * Pass the bundled Gabarito and Figtree families (res/font) as [display] and [text].
 */
@Composable
fun TmlTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    display: FontFamily = FontFamily.Default,
    text: FontFamily = FontFamily.Default,
    content: @Composable () -> Unit,
) {
    val scale = TmlTypeScale(display, text)
    CompositionLocalProvider(
        LocalTmlColors provides if (darkTheme) TmlDarkColors else TmlLightColors,
        LocalTmlTypeScale provides scale,
    ) {
        MaterialTheme(
            colorScheme = if (darkTheme) TmlDarkColorScheme else TmlLightColorScheme,
            typography = tmlTypography(scale),
            content = content,
        )
    }
}

/** Accessors for the current theme: `TmlTheme.colors.lamplight`, `TmlTheme.type.title2`. */
object TmlTheme {
    val colors: TmlColors
        @Composable @ReadOnlyComposable get() = LocalTmlColors.current
    val type: TmlTypeScale
        @Composable @ReadOnlyComposable get() = LocalTmlTypeScale.current
}
